for r in old:
 i=r['test_id'];rows.append(dict(test_id=i,title=r['title'],gap_class=assignment[i],exact_next_gate=r['next_cheapest_check'],original_card_file=r['source_file'],news_view='priority_if_material_case' if i in news_top else 'not_in_short_editorial_slate',news_reason=news_top.get(i,'Outside this deliberately small slate, not a judgment of no public interest; see the original card consequence/basis.'),meaningful_check_shortlist_rank=cheap_order.index(i)+1 if i in cheap_order else None,news_potential_shortlist_rank=news_order.index(i)+1 if i in news_order else None,full_case_feasible=False,cost_time='Unknown: no measured complete-test runtime or acquisition cost',ranking_basis='Manual original-record-gap judgment; deterministic display only, no mixed raw scores',prior_plumbing_readiness=r['readiness_tier'],prior_next_step_effort=r['effort_tier']))
