exp('cheapest-meaningful-checks',sorted([r for r in rows if r['meaningful_check_shortlist_rank']],key=lambda r:r['meaningful_check_shortlist_rank']))
exp('strongest-news-potential',sorted([r for r in rows if r['news_potential_shortlist_rank']],key=lambda r:r['news_potential_shortlist_rank']))
